/**
 * @nexora/module-integrations — WebhookEndpoint aggregate root.
 *
 * A workspace-scoped webhook endpoint (BACKEND.md §9, V1-9 "webhooks out"):
 * an outbound URL that receives signed payloads when subscribed business
 * events fire. The aggregate owns the URL, the signing secret (generated by
 * the application, never returned by reads), the subscribed event types,
 * and the enabled flag. Delivery itself is a service concern — the receipt
 * (which events were delivered and with what outcome) lives in the
 * {@link WebhookDelivery} aggregate (SAD §5.x delivery receipts).
 *
 * Security invariant: the secret is created here and exposed EXACTLY once
 * (at creation) through the application layer — reads only ever surface a
 * masked value. Subscriptions are an allowlist: only catalog event types
 * the caller may choose are accepted.
 */

import type { EventEnvelope } from '@nexora/shared/events';
import { prefixedId } from '@nexora/shared/ids';
import { nowIso } from '@nexora/shared/time';
import type { TenantId, WorkspaceId } from '@nexora/contracts/common';

import type { IntegrationEventContext } from '../events/index.js';
import { webhookCreatedEvent, webhookUpdatedEvent } from '../events/index.js';

/** The event types a webhook endpoint may subscribe to. */
export const WEBHOOK_SUBSCRIBABLE_EVENTS: readonly string[] = [
  'project.created',
  'project.activated',
  'employee.created',
  'employee.hired',
  'document.available',
  'knowledge.indexed',
  'knowledge.article.published',
  'calendar.event.created',
  'calendar.event.updated',
  'calendar.event.cancelled',
  'workspace.plugin_installed',
  'workspace.plugin_updated',
  'workspace.plugin_removed',
  'workflow.completed',
  'workflow.failed',
  'workflow.waiting_for_approval',
];

/** Input for creating a {@link WebhookEndpoint}. */
export interface CreateWebhookEndpointInput {
  /** The owning organization (tenant) id. */
  organizationId: TenantId;
  /** The owning workspace id. */
  workspaceId: WorkspaceId;
  /** The HTTPS URL that receives signed payloads. */
  url: string;
  /** The event types to subscribe to (subset of {@link WEBHOOK_SUBSCRIBABLE_EVENTS}). */
  eventTypes: readonly string[];
}

/** A persistence snapshot of the {@link WebhookEndpoint} aggregate. */
export interface WebhookEndpointSnapshot {
  /** The endpoint id. */
  id: string;
  /** The owning organization (tenant) id. */
  organizationId: TenantId;
  /** The owning workspace id. */
  workspaceId: WorkspaceId;
  /** The target URL. */
  url: string;
  /** The HMAC signing secret (only surfaced once at creation). */
  secret: string;
  /** The subscribed event types. */
  eventTypes: readonly string[];
  /** Whether the endpoint is enabled. */
  enabled: boolean;
  /** ISO-8601 UTC creation time. */
  createdAt: string;
  /** ISO-8601 UTC last mutation time. */
  updatedAt: string;
  /** Monotonic version for optimistic concurrency. */
  version: number;
}

/**
 * The {@link WebhookEndpoint} aggregate root. Use
 * {@link WebhookEndpoint.create} to construct.
 */
export class WebhookEndpoint {
  #id: string;
  readonly #organizationId: TenantId;
  readonly #workspaceId: WorkspaceId;
  // Not `readonly`: reassigned by `updateUrl`/`updateSubscription`.
  #url: string;
  #secret: string;
  #eventTypes: readonly string[];
  #enabled: boolean;
  readonly #createdAt: string;
  #updatedAt: string;
  #version: number;
  readonly #events: EventEnvelope[] = [];

  private constructor(input: CreateWebhookEndpointInput, secret: string, now: string) {
    this.#id = prefixedId('whk') as string;
    this.#organizationId = input.organizationId;
    this.#workspaceId = input.workspaceId;
    this.#url = input.url;
    this.#secret = secret;
    this.#eventTypes = [...input.eventTypes];
    this.#enabled = true;
    this.#createdAt = now;
    this.#updatedAt = now;
    this.#version = 1;
  }

  /**
   * Creates a new endpoint (enabled by default) and records a
   * {@link integration.webhook.created} event.
   *
   * @param input   - endpoint data (URL + subscription).
   * @param secret  - the generated HMAC signing secret (exposed once).
   * @param context - event context.
   * @param now     - ISO-8601 UTC creation time.
   */
  static create(
    input: CreateWebhookEndpointInput,
    secret: string,
    context: IntegrationEventContext,
    now = nowIso(),
  ): WebhookEndpoint {
    const endpoint = new WebhookEndpoint(input, secret, now);
    endpoint.#events.push(
      webhookCreatedEvent(context, {
        endpointId: endpoint.#id,
        workspaceId: endpoint.#workspaceId,
        eventTypes: endpoint.#eventTypes,
        enabled: endpoint.#enabled,
      }),
    );
    return endpoint;
  }

  /** The endpoint id. */
  get id(): string {
    return this.#id;
  }

  /** The owning organization (tenant) id. */
  get organizationId(): TenantId {
    return this.#organizationId;
  }

  /** The owning workspace id. */
  get workspaceId(): WorkspaceId {
    return this.#workspaceId;
  }

  /** The target URL. */
  get url(): string {
    return this.#url;
  }

  /** The HMAC signing secret. */
  get secret(): string {
    return this.#secret;
  }

  /** The subscribed event types. */
  get eventTypes(): readonly string[] {
    return this.#eventTypes;
  }

  /** Whether the endpoint is enabled. */
  get enabled(): boolean {
    return this.#enabled;
  }

  /** ISO-8601 UTC creation time. */
  get createdAt(): string {
    return this.#createdAt;
  }

  /** ISO-8601 UTC last mutation time. */
  get updatedAt(): string {
    return this.#updatedAt;
  }

  /** Monotonic version for optimistic concurrency. */
  get version(): number {
    return this.#version;
  }

  /** Whether this endpoint subscribes to the given event type. */
  subscribesTo(eventType: string): boolean {
    return this.#enabled && this.#eventTypes.includes(eventType);
  }

  /**
   * Updates the target URL and subscribed event types. Emits a
   * {@link integration.webhook.updated} event.
   */
  update(
    input: { url: string; eventTypes: readonly string[] },
    context: IntegrationEventContext,
    now = nowIso(),
  ): void {
    this.#url = input.url;
    this.#eventTypes = [...input.eventTypes];
    this.#updatedAt = now;
    this.#version += 1;
    this.#events.push(
      webhookUpdatedEvent(context, {
        endpointId: this.#id,
        workspaceId: this.#workspaceId,
        eventTypes: this.#eventTypes,
        enabled: this.#enabled,
      }),
    );
  }

  /**
   * Enables or disables the endpoint. A disabled endpoint never receives
   * deliveries but is retained (re-enabling is a normal operation).
   */
  setEnabled(enabled: boolean, context: IntegrationEventContext, now = nowIso()): void {
    if (this.#enabled === enabled) {
      return;
    }
    this.#enabled = enabled;
    this.#updatedAt = now;
    this.#version += 1;
    this.#events.push(
      webhookUpdatedEvent(context, {
        endpointId: this.#id,
        workspaceId: this.#workspaceId,
        eventTypes: this.#eventTypes,
        enabled: this.#enabled,
      }),
    );
  }

  /**
   * Produces a persistence snapshot of the endpoint.
   */
  static snapshot(endpoint: WebhookEndpoint): WebhookEndpointSnapshot {
    return {
      id: endpoint.id,
      organizationId: endpoint.organizationId,
      workspaceId: endpoint.workspaceId,
      url: endpoint.url,
      secret: endpoint.secret,
      eventTypes: endpoint.eventTypes,
      enabled: endpoint.enabled,
      createdAt: endpoint.createdAt,
      updatedAt: endpoint.updatedAt,
      version: endpoint.version,
    };
  }

  /**
   * Reconstructs a {@link WebhookEndpoint} from a persistence snapshot
   * without emitting domain events (DDD reconstitution factory).
   */
  static hydrate(snapshot: WebhookEndpointSnapshot): WebhookEndpoint {
    const endpoint = new WebhookEndpoint(
      {
        organizationId: snapshot.organizationId,
        workspaceId: snapshot.workspaceId,
        url: snapshot.url,
        eventTypes: snapshot.eventTypes,
      },
      snapshot.secret,
      snapshot.createdAt,
    );
    endpoint.#id = snapshot.id;
    endpoint.#enabled = snapshot.enabled;
    endpoint.#updatedAt = snapshot.updatedAt;
    endpoint.#version = snapshot.version;
    return endpoint;
  }

  /** Returns and clears the recorded domain events. */
  pullDomainEvents(): readonly EventEnvelope[] {
    const events = [...this.#events];
    this.#events.length = 0;
    return events;
  }
}
